+import sales from './sales.json' with {type:'json'};
+
+const SALES_REPORT_TOOL = {
+  name: 'sales_report',
+  description: 'Sum sales rows within an inclusive date range. Returns the total amount and the number of matching rows as text.',
+  inputSchema: {
+    type: 'object',
+    properties: {
+      start_date: { type: 'string', description: 'Inclusive start date in ISO YYYY-MM-DD format.' },
+      end_date: { type: 'string', description: 'Inclusive end date in ISO YYYY-MM-DD format.' }
+    },
+    required: ['start_date', 'end_date'],
+    additionalProperties: false
+  }
+};
+
+const ALLOWED_FIELDS = ['start_date', 'end_date'];
+
+// Parse a strict ISO calendar date (YYYY-MM-DD). Returns a UTC Date or null when malformed.
+function parseISODate(value) {
+  if (typeof value !== 'string') return null;
+  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
+  if (!match) return null;
+  const year = Number(match[1]);
+  const month = Number(match[2]);
+  const day = Number(match[3]);
+  const date = new Date(Date.UTC(year, month - 1, day));
+  if (
+    date.getUTCFullYear() !== year ||
+    date.getUTCMonth() !== month - 1 ||
+    date.getUTCDate() !== day
+  ) {
+    return null;
+  }
+  return date;
+}
+
+export async function listTools() {
+  return [SALES_REPORT_TOOL];
+}
+
+export async function callTool(name, args = {}) {
+  if (name !== 'sales_report') {
+    throw new Error(`Unknown tool: ${name}`);
+  }
+
+  // Reject any fields outside the declared schema.
+  for (const key of Object.keys(args)) {
+    if (!ALLOWED_FIELDS.includes(key)) {
+      throw new Error(`Unknown field: ${key}`);
+    }
+  }
+
+  if (args.start_date === undefined) {
+    throw new Error('start_date is required');
+  }
+  if (args.end_date === undefined) {
+    throw new Error('end_date is required');
+  }
+
+  const start = parseISODate(args.start_date);
+  if (!start) {
+    throw new Error(`Invalid start_date: ${args.start_date}`);
+  }
+  const end = parseISODate(args.end_date);
+  if (!end) {
+    throw new Error(`Invalid end_date: ${args.end_date}`);
+  }
+
+  if (start.getTime() > end.getTime()) {
+    throw new Error('start_date must not be after end_date');
+  }
+
+  const startTime = start.getTime();
+  const endTime = end.getTime();
+
+  let total = 0;
+  let count = 0;
+  for (const row of sales) {
+    const rowDate = parseISODate(row.date);
+    if (!rowDate) continue;
+    const t = rowDate.getTime();
+    if (t >= startTime && t <= endTime) {
+      total += Number(row.amount);
+      count += 1;
+    }
+  }
+
+  return {
+    content: [
+      { type: 'text', text: `Total: ${total}, Rows: ${count}` }
+    ]
+  };
+}
